+   // only unset the default on an explicit delete of the sequence flow
+   this.preExecute('elements.delete', function(event) {
+     var context  = event.context,
+         elements = context.elements;
+
+     // loop through all deleted elements, look for the default flow
+     elements.forEach(function(el) {
+       if (is(el, 'bpmn:SequenceFlow')) {
+         var connection = el,
+             source     = connection.source;
+
